"""matplotlib.text — text handling stubs."""

import sys as _sys


# Shared no-op fallback for unknown Text methods.
_text_warned = set()

def _text_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _text_warned:
        _text_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] text.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Text:
    """Stub Text artist."""
    __getattr__ = _text_getattr_fallback

    def __init__(self, x=0, y=0, text='', **kwargs):
        self._x = x
        self._y = y
        self._text = str(text) if text is not None else ''
        self._fontsize = kwargs.get('fontsize', kwargs.get('size', 12))
        self._fontfamily = kwargs.get('fontfamily', kwargs.get('family', 'sans-serif'))
        self._fontweight = kwargs.get('fontweight', kwargs.get('weight', 'normal'))
        self._fontstyle = kwargs.get('fontstyle', kwargs.get('style', 'normal'))
        self._fontvariant = kwargs.get('fontvariant', 'normal')
        self._fontstretch = kwargs.get('fontstretch', 'normal')
        self._color = kwargs.get('color', 'black')
        self._backgroundcolor = kwargs.get('backgroundcolor', None)
        self._alpha = kwargs.get('alpha', None)
        self._ha = kwargs.get('ha', kwargs.get('horizontalalignment', 'left'))
        self._va = kwargs.get('va', kwargs.get('verticalalignment', 'baseline'))
        self._ma = kwargs.get('ma', kwargs.get('multialignment', None))
        self._rotation = kwargs.get('rotation', 0)
        self._rotation_mode = kwargs.get('rotation_mode', None)
        self._linespacing = kwargs.get('linespacing', 1.2)
        self._bbox = kwargs.get('bbox', None)
        self._transform = kwargs.get('transform', None)
        self._wrap = kwargs.get('wrap', False)
        self._usetex = kwargs.get('usetex', None)
        self._parse_math = kwargs.get('parse_math', True)
        self._url = kwargs.get('url', None)
        self._gid = kwargs.get('gid', None)
        self._zorder = kwargs.get('zorder', 3)
        self._visible = True
        self._in_layout = True
        self._rasterized = False
        self._animated = False
        self._snap = None
        self._path_effects = []
        self._picker = None
        self._clip_box = None
        self._clip_on = True
        self._clip_path = None
        self._label = kwargs.get('label', '')

    # Text
    def get_text(self):        return self._text
    def set_text(self, t):     self._text = str(t) if t is not None else ''
    # Font properties
    def get_fontsize(self):    return self._fontsize
    def set_fontsize(self, s): self._fontsize = s
    def get_size(self):        return self._fontsize
    def set_size(self, s):     self._fontsize = s
    def get_fontfamily(self):  return self._fontfamily
    def set_fontfamily(self, f): self._fontfamily = f
    def get_family(self):      return self._fontfamily
    def set_family(self, f):   self._fontfamily = f
    def get_fontweight(self):  return self._fontweight
    def set_fontweight(self, w): self._fontweight = w
    def get_weight(self):      return self._fontweight
    def set_weight(self, w):   self._fontweight = w
    def get_fontstyle(self):   return self._fontstyle
    def set_fontstyle(self, s): self._fontstyle = s
    def get_style(self):       return self._fontstyle
    def set_style(self, s):    self._fontstyle = s
    def get_fontvariant(self): return self._fontvariant
    def set_fontvariant(self, v): self._fontvariant = v
    def get_variant(self):     return self._fontvariant
    def set_variant(self, v):  self._fontvariant = v
    def get_fontstretch(self): return self._fontstretch
    def set_fontstretch(self, s): self._fontstretch = s
    def get_stretch(self):     return self._fontstretch
    def set_stretch(self, s):  self._fontstretch = s
    def get_fontproperties(self):
        return None
    def set_fontproperties(self, fp): pass
    def set_font_properties(self, fp): pass
    # Color
    def get_color(self):       return self._color
    def set_color(self, c):    self._color = c
    def get_backgroundcolor(self): return self._backgroundcolor
    def set_backgroundcolor(self, c): self._backgroundcolor = c
    # Alignment
    def get_ha(self):              return self._ha
    def get_horizontalalignment(self): return self._ha
    def set_ha(self, ha):          self._ha = ha
    def set_horizontalalignment(self, ha): self._ha = ha
    def get_va(self):              return self._va
    def get_verticalalignment(self): return self._va
    def set_va(self, va):          self._va = va
    def set_verticalalignment(self, va): self._va = va
    def get_ma(self):              return self._ma
    def get_multialignment(self):  return self._ma
    def set_ma(self, ma):          self._ma = ma
    def set_multialignment(self, ma): self._ma = ma
    def get_rotation(self):        return self._rotation
    def set_rotation(self, r):     self._rotation = r
    def get_rotation_mode(self):   return self._rotation_mode
    def set_rotation_mode(self, m): self._rotation_mode = m
    def get_linespacing(self):     return self._linespacing
    def set_linespacing(self, l):  self._linespacing = l
    # Position
    def get_position(self):    return (self._x, self._y)
    def set_position(self, xy): self._x, self._y = xy
    def get_x(self):           return self._x
    def set_x(self, x):        self._x = x
    def get_y(self):           return self._y
    def set_y(self, y):        self._y = y
    # Bbox / transform / clipping
    def get_bbox_patch(self):  return self._bbox
    def set_bbox(self, b):     self._bbox = b
    def get_transform(self):   return self._transform
    def set_transform(self, t): self._transform = t
    def get_clip_box(self):    return self._clip_box
    def set_clip_box(self, b): self._clip_box = b
    def get_clip_on(self):     return self._clip_on
    def set_clip_on(self, b):  self._clip_on = bool(b)
    def get_clip_path(self):   return self._clip_path
    def set_clip_path(self, p): self._clip_path = p
    # Wrap / parsing
    def get_wrap(self):        return self._wrap
    def set_wrap(self, b):     self._wrap = bool(b)
    def get_usetex(self):      return self._usetex
    def set_usetex(self, b):   self._usetex = b
    def get_parse_math(self):  return self._parse_math
    def set_parse_math(self, b): self._parse_math = bool(b)
    # Metadata + state
    def get_url(self):         return self._url
    def set_url(self, u):      self._url = u
    def get_gid(self):         return self._gid
    def set_gid(self, g):      self._gid = g
    def get_zorder(self):      return self._zorder
    def set_zorder(self, z):   self._zorder = z
    def get_visible(self):     return self._visible
    def set_visible(self, v):  self._visible = bool(v)
    def get_alpha(self):       return self._alpha
    def set_alpha(self, a):    self._alpha = a
    def get_in_layout(self):   return self._in_layout
    def set_in_layout(self, b): self._in_layout = bool(b)
    def get_rasterized(self):  return self._rasterized
    def set_rasterized(self, b): self._rasterized = bool(b)
    def get_animated(self):    return self._animated
    def set_animated(self, b): self._animated = bool(b)
    def get_snap(self):        return self._snap
    def set_snap(self, s):     self._snap = s
    def get_path_effects(self): return list(self._path_effects)
    def set_path_effects(self, pe): self._path_effects = list(pe) if pe else []
    def get_picker(self):      return self._picker
    def set_picker(self, p):   self._picker = p
    def get_label(self):       return self._label
    def set_label(self, l):    self._label = l
    # Lifecycle / draw
    def remove(self):          pass
    def draw(self, renderer):  pass
    def contains(self, ev):    return False, {}
    def get_window_extent(self, renderer=None, dpi=None):
        return None
    def get_tightbbox(self, renderer=None):
        return None
    def update_bbox_position_size(self, renderer):
        pass
    def update_from(self, other):
        for attr in ('text', 'fontsize', 'color', 'rotation',
                     'ha', 'va', 'alpha', 'visible', 'zorder'):
            getter = getattr(other, f'get_{attr}', None)
            setter = getattr(self, f'set_{attr}', None)
            if getter and setter:
                try: setter(getter())
                except Exception: pass
    def update(self, props):
        for k, v in (props or {}).items():
            setter = getattr(self, f'set_{k}', None)
            if setter is not None:
                try: setter(v)
                except Exception: pass
    def findobj(self, match=None, include_self=True):
        return [self] if include_self else []


class Annotation(Text):
    """Stub Annotation artist."""

    def __init__(self, text, xy, xytext=None, xycoords='data',
                 textcoords=None, arrowprops=None, annotation_clip=None, **kwargs):
        super().__init__(xy[0], xy[1], text, **kwargs)
        self.xy = xy
        self.xytext = xytext
        self.xycoords = xycoords
        self.arrowprops = arrowprops


