class TextWithDash(Text):
    """Text with an optional leader dash, used by some annotation styles.
    Upstream deprecated it but kept the symbol; we keep it as a
    :class:`Text` subclass that stores the dash parameters."""

    def __init__(self, x=0, y=0, text='', *, dashlength=0.0, dashdirection=0,
                 dashrotation=None, dashpad=3, dashpush=0, **kwargs):
        super().__init__(x, y, text, **kwargs)
        self._dashlength = dashlength
        self._dashdirection = dashdirection
        self._dashrotation = dashrotation
        self._dashpad = dashpad
        self._dashpush = dashpush

    def get_dashlength(self):       return self._dashlength
    def set_dashlength(self, dl):   self._dashlength = dl
    def get_dashdirection(self):    return self._dashdirection
    def set_dashdirection(self, d): self._dashdirection = d


class OffsetFrom:
    """Callable transform that returns a position offset from a target
    artist. ``Annotation`` uses it to anchor at a point ``(x, y)``
    measured from another artist's bounding box. The shim records the
    parameters and returns the unmodified offset when called."""

    def __init__(self, artist, ref_coord, unit='points'):
        self._artist = artist
        self._ref_coord = ref_coord
        self._unit = unit

    def __call__(self, renderer=None):
        return self._ref_coord


def get_rotation(rotation):
    """Convert a rotation spec to an angle in degrees.
    Accepts ``None`` (returns 0), a number, or the strings
    ``'horizontal'`` / ``'vertical'``.
    """
    if rotation is None:
        return 0.0
    if isinstance(rotation, str):
        s = rotation.lower()
        if s == 'horizontal':
            return 0.0
        if s == 'vertical':
            return 90.0
        try:
            return float(rotation)
        except ValueError as e:
            raise ValueError(f"rotation must be 'horizontal', 'vertical', or"
                             f" a number, got {rotation!r}") from e
    return float(rotation)


