def _attach_text_methods(cls):
    """Fill in the missing :class:`Text` getter/setter surface."""

    def contains(self, mouseevent):       return False, {}
    def draw(self, renderer):              pass
    def get_antialiased(self):             return getattr(self, '_aa', True)
    def set_antialiased(self, b):          self._aa = bool(b)
    def get_bbox_patch(self):              return getattr(self, '_bbox_patch', None)
    def set_bbox(self, rectprops):         self._bbox_patch = rectprops
    def get_clip_on(self):                 return getattr(self, '_clip_on', True)
    def set_clip_on(self, b):              self._clip_on = bool(b)

    def get_fontfamily(self):              return getattr(self, '_fontfamily', ['sans-serif'])
    def set_fontfamily(self, family):      self._fontfamily = family if isinstance(family, list) else [family]
    def get_fontname(self):                return self.get_fontfamily()[0]
    def set_fontname(self, n):             self.set_fontfamily(n)
    def get_fontproperties(self):
        from matplotlib.font_manager import FontProperties
        return getattr(self, '_fp', None) or FontProperties()
    def set_fontproperties(self, fp):      self._fp = fp
    def get_font_properties(self):         return self.get_fontproperties()
    def set_font_properties(self, fp):     self.set_fontproperties(fp)

    def get_fontstyle(self):               return getattr(self, '_fontstyle', 'normal')
    def set_fontstyle(self, s):            self._fontstyle = s
    def get_fontvariant(self):             return getattr(self, '_fontvariant', 'normal')
    def set_fontvariant(self, v):          self._fontvariant = v
    def get_fontweight(self):              return getattr(self, '_fontweight', 'normal')
    def set_fontweight(self, w):           self._fontweight = w
    def get_stretch(self):                 return getattr(self, '_stretch', 'normal')
    def set_stretch(self, s):              self._stretch = s
    def get_fontsize(self):                return self._fontsize
    def set_fontsize(self, s):             self._fontsize = s
    def get_size(self):                    return self._fontsize
    def set_size(self, s):                 self._fontsize = s
    def get_weight(self):                  return self.get_fontweight()
    def set_weight(self, w):               self.set_fontweight(w)
    def get_style(self):                   return self.get_fontstyle()
    def set_style(self, s):                self.set_fontstyle(s)
    def get_variant(self):                 return self.get_fontvariant()
    def set_variant(self, v):              self.set_fontvariant(v)
    def get_family(self):                  return self.get_fontfamily()
    def set_family(self, f):               self.set_fontfamily(f)
    def get_name(self):                    return self.get_fontname()
    def set_name(self, n):                 self.set_fontname(n)

    def get_horizontalalignment(self):     return getattr(self, '_ha', 'left')
    def set_horizontalalignment(self, ha): self._ha = ha
    def get_ha(self):                      return self.get_horizontalalignment()
    def set_ha(self, ha):                  self.set_horizontalalignment(ha)
    def get_verticalalignment(self):       return getattr(self, '_va', 'baseline')
    def set_verticalalignment(self, va):   self._va = va
    def get_va(self):                      return self.get_verticalalignment()
    def set_va(self, va):                  self.set_verticalalignment(va)
    def get_multialignment(self):          return getattr(self, '_ma', None)
    def set_multialignment(self, ma):      self._ma = ma
    def get_linespacing(self):             return getattr(self, '_linespacing', 1.2)
    def set_linespacing(self, s):          self._linespacing = float(s)

    def get_math_fontfamily(self):         return getattr(self, '_math_ff', 'dejavusans')
    def set_math_fontfamily(self, f):      self._math_ff = f
    def get_parse_math(self):              return getattr(self, '_parse_math', True)
    def set_parse_math(self, b):           self._parse_math = bool(b)

    def get_rotation(self):                return getattr(self, '_rotation', 0.0)
    def set_rotation(self, r):
        from matplotlib.text import get_rotation
        self._rotation = get_rotation(r)
    def get_rotation_mode(self):           return getattr(self, '_rot_mode', None)
    def set_rotation_mode(self, m):        self._rot_mode = m
    def get_transform_rotates_text(self):  return getattr(self, '_trt', False)
    def set_transform_rotates_text(self, b): self._trt = bool(b)

    def get_usetex(self):                  return getattr(self, '_usetex', None)
    def set_usetex(self, b):               self._usetex = b
    def get_wrap(self):                    return getattr(self, '_wrap', False)
    def set_wrap(self, b):                 self._wrap = bool(b)

    def get_unitless_position(self):       return (self._x, self._y)
    def get_window_extent(self, renderer=None, dpi=None): return None
    def get_prop_tup(self):                return (self._text, self._fontsize)
    def update(self, props):
        if isinstance(props, dict):
            for k, v in props.items():
                setter = getattr(self, f'set_{k}', None)
                if setter: setter(v)
    def update_from(self, other):
        for attr in ('text', 'fontsize', 'color'):
            getter = getattr(other, f'get_{attr}', None)
            setter = getattr(self, f'set_{attr}', None)
            if getter and setter:
                try: setter(getter())
                except Exception: pass
    def update_bbox_position_size(self, renderer=None): pass

    def set_color(self, color):    self._color = color
    def set_x(self, x):            self._x = x
    def set_y(self, y):            self._y = y
    def set_position(self, xy):    self._x, self._y = xy

    def get_x(self):               return self._x
    def get_y(self):               return self._y

    _l = locals()
    for n in ('contains', 'draw', 'get_antialiased', 'set_antialiased',
              'get_bbox_patch', 'set_bbox', 'get_clip_on', 'set_clip_on',
              'get_fontfamily', 'set_fontfamily', 'get_fontname', 'set_fontname',
              'get_fontproperties', 'set_fontproperties',
              'get_font_properties', 'set_font_properties',
              'get_fontstyle', 'set_fontstyle', 'get_fontvariant',
              'set_fontvariant', 'get_fontweight', 'set_fontweight',
              'get_stretch', 'set_stretch',
              'get_fontsize', 'set_fontsize', 'get_size', 'set_size',
              'get_weight', 'set_weight', 'get_style', 'set_style',
              'get_variant', 'set_variant', 'get_family', 'set_family',
              'get_name', 'set_name',
              'get_horizontalalignment', 'set_horizontalalignment',
              'get_ha', 'set_ha',
              'get_verticalalignment', 'set_verticalalignment',
              'get_va', 'set_va',
              'get_multialignment', 'set_multialignment',
              'get_linespacing', 'set_linespacing',
              'get_math_fontfamily', 'set_math_fontfamily',
              'get_parse_math', 'set_parse_math',
              'get_rotation', 'set_rotation', 'get_rotation_mode',
              'set_rotation_mode', 'get_transform_rotates_text',
              'set_transform_rotates_text',
              'get_usetex', 'set_usetex', 'get_wrap', 'set_wrap',
              'get_unitless_position', 'get_window_extent', 'get_prop_tup',
              'update', 'update_from', 'update_bbox_position_size',
              'set_color', 'set_x', 'set_y', 'set_position',
              'get_x', 'get_y'):
        if n in _l:
            setattr(cls, n, _l[n])


_attach_text_methods(Text)


def _attach_annotation_methods(cls):
    """Annotation-specific additions on top of Text."""

    def contains(self, mouseevent):    return False, {}
    def draw(self, renderer):           pass
    def set_figure(self, fig):          self.figure = fig

    @property
    def anncoords(self):
        return getattr(self, '_anncoords', 'data')

    @anncoords.setter
    def anncoords(self, v):
        self._anncoords = v

    def get_anncoords(self):       return self.anncoords
    def set_anncoords(self, v):    self.anncoords = v

    def get_tightbbox(self, renderer=None): return None
    def get_window_extent(self, renderer=None): return None

    @property
    def xyann(self):
        return getattr(self, 'xytext', None) or self.xy

    @xyann.setter
    def xyann(self, v):
        self.xytext = v

    @property
    def xycoords(self):
        return getattr(self, '_xycoords', 'data')

    @xycoords.setter
    def xycoords(self, v):
        self._xycoords = v

    def update_positions(self, renderer=None): pass

    cls.contains = contains
    cls.draw = draw
    cls.set_figure = set_figure
    cls.anncoords = anncoords
    cls.get_anncoords = get_anncoords
    cls.set_anncoords = set_anncoords
    cls.get_tightbbox = get_tightbbox
    cls.get_window_extent = get_window_extent
    cls.xyann = xyann
    cls.xycoords = xycoords
    cls.update_positions = update_positions


_attach_annotation_methods(Annotation)


